                                else if (*format == 'z' || *format == 'x')
                                        last_bg = '\0';
                        }
                        format++;
                } else {
                        /* % at end of string */
                        format++;
                        g_string_append_c(str, '%');
                        g_string_append_c(str, '%');
                }
        }

        ret = str->str;
        g_string_free(str, FALSE);
        return ret;
